export function parseCsv(text) {
  const rows = [];
  let currentRow = [];
  let currentField = '';
  let inQuotes = false;
  let i = 0;

  while (i < text.length) {
    const char = text[i];
    const nextChar = i + 1 < text.length ? text[i + 1] : null;

    if (inQuotes) {
      if (char === '"') {
        if (nextChar === '"') {
          // Doubled quote ("") means literal quote
          currentField += '"';
          i += 2;
          continue;
        } else {
          // End of quoted field
          inQuotes = false;
          i++;
          continue;
        }
      } else {
        // Inside quotes, take character literally (including commas and newlines)
        currentField += char;
        i++;
        continue;
      }
    } else {
      // Not in quotes
      if (char === '"') {
        // Start of quoted field
        inQuotes = true;
        i++;
        continue;
      } else if (char === ',') {
        // Field separator
        currentRow.push(currentField);
        currentField = '';
        i++;
        continue;
      } else if (char === '\r') {
        // Check for \r\n or just \r
        if (nextChar === '\n') {
          // \r\n - record separator
          currentRow.push(currentField);
          currentField = '';
          rows.push(currentRow);
          currentRow = [];
          i += 2;
          continue;
        } else {
          // Just \r - record separator
          currentRow.push(currentField);
          currentField = '';
          rows.push(currentRow);
          currentRow = [];
          i++;
          continue;
        }
      } else if (char === '\n') {
        // \n - record separator
        currentRow.push(currentField);
        currentField = '';
        rows.push(currentRow);
        currentRow = [];
        i++;
        continue;
      } else {
        // Regular character
        currentField += char;
        i++;
        continue;
      }
    }
  }

  // Add final field and row if any
  currentRow.push(currentField);
  if (currentRow.length > 0 || currentField !== '') {
    rows.push(currentRow);
  }

  return rows;
}
